# Windows Native Terminal Story Animation - No Python Required
# Runs in PowerShell 5.1 / 7+ and CMD via: irm <URL> | iex
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}
try { [Console]::CursorVisible = $false } catch {}
try {
    $rawB64 = ""
    $bytes = [System.Convert]::FromBase64String($rawB64)
    $ms = New-Object System.IO.MemoryStream(,$bytes)
    $gz = New-Object System.IO.Compression.GZipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
    $outMs = New-Object System.IO.MemoryStream
    $gz.CopyTo($outMs)
    $decomp = [System.Text.Encoding]::UTF8.GetString($outMs.ToArray())
    $frames = $decomp.Split([char]0)

    $fps = 15
    $intervalMs = [int](1000 / $fps)
    $sw = [System.Diagnostics.Stopwatch]::StartNew()

    [System.Console]::Out.Write("`e[2J`e[H")
    for ($i = 0; $i -lt $frames.Length; $i++) {
        $targetMs = [int]($i * $intervalMs)
        $frame = $frames[$i]
        [System.Console]::Out.Write($frame)

        $wait = $targetMs - $sw.ElapsedMilliseconds
        if ($wait -gt 0) {
            [System.Threading.Thread]::Sleep($wait)
        }
    }
} finally {
    try { [Console]::CursorVisible = $true } catch {}
    [System.Console]::Out.Write("`e[0m`n")
}
